'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawnSync}=require('node:child_process');
const {record,env}=require('./fixtures.cjs');
const ROOT=process.env.RUNNER_TEMP??process.env.TMPDIR;assert.ok(typeof ROOT==='string'&&path.isAbsolute(ROOT));if(process.platform==='darwin')assert.ok(ROOT.startsWith('/Volumes/CodexE1Work/tmp'));
function setup(){const d=fs.mkdtempSync(path.join(ROOT,'scanner-worker-custody-'));for(const name of ['index.cjs','backend.cjs','schema.cjs','worker.cjs'])fs.copyFileSync(path.join(__dirname,name),path.join(d,name));return d;}
test('substituted own helper is refused before any compile or child runtime',()=>{const d=setup();try{fs.writeFileSync(path.join(d,'schema.cjs'),"require('node:fs').writeSync(2,'PUBLIC_UNCHECKED_HELPER_SENTINEL');");const source=`try{require(${JSON.stringify(path.join(d,'index.cjs'))});process.exitCode=9;}catch(e){require('node:fs').writeSync(1,e.message);}`;const r=spawnSync(process.execPath,['-e',source],{env:{PATH:process.env.PATH,TMPDIR:ROOT},encoding:'utf8',timeout:10000});assert.equal(r.status,0);assert.equal(r.stdout,'ACTION_SOURCE_HOLD');assert.equal(r.stderr,'');}finally{fs.rmSync(d,{recursive:true,force:true});}});
test('postcapture own-source pathname swaps do not affect actual worker compile',()=>{const d=setup();try{const source=`const s=require(${JSON.stringify(path.join(d,'index.cjs'))}),fs=require('node:fs');for(const name of ['schema.cjs','backend.cjs','worker.cjs'])fs.writeFileSync(${JSON.stringify(d)}+'/'+name,"require('node:fs').writeSync(2,'PUBLIC_UNCHECKED_WORKER_SENTINEL');");s.phaseWorker(Buffer.from(${JSON.stringify(JSON.stringify(record()))}),${JSON.stringify(env())}).then(()=>process.exitCode=9).catch(e=>fs.writeSync(1,e.message));`;const r=spawnSync(process.execPath,['-e',source],{env:{PATH:process.env.PATH,TMPDIR:ROOT},encoding:'utf8',timeout:10000});assert.equal(r.status,0);assert.equal(r.stdout,'DURABLE_RECEIPT_HOLD');assert.equal(r.stderr,'');}finally{fs.rmSync(d,{recursive:true,force:true});}});
